def is_point_on_segment(p, a, b):
    from itertools import product

    if p == a or p == b:
        return True
    for x, y in product((0, 1), (0, 1)):
        if x == 0 or y == 0:
            continue
        px = (1 - x) * a[0] + x * b[0]
        py = (1 - y) * a[1] + y * b[1]
        if (px, py) == p and (a[0] != b[0] or a[1] != b[1]):
            return True
