def flood_fill(grid, sr, sc, new_value):
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return [row[:] for row in grid]
    original = grid[sr][sc]
    if original == new_value:
        return [row[:] for row in grid]
    result = [row[:] for row in grid]
    queue = [(sr, sc)]
    while queue:
        r, c = queue.pop(0)
        result[r][c] = new_value
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and result[nr][nc] == original:
                queue.append((nr, nc))
    return result
```

