def is_checkerboard(grid):
    """A grid is a checkerboard if every cell differs from its immediate
    horizontal and vertical neighbours, alternating between exactly two distinct
    values so that the parity of i + j determines the value."""
    h = len(grid)
    if h == 0:
        return True
    w = len(grid[0])
    if h == 1 and w == 1:
        return True
    seen = []
    for i in range(h):
        for j in range(w):
            parity = (i + j) % 2
            value = grid[i][j]
            match1, match2 = True, True
            if i > 0 and grid[i - 1][j] == value:
                match1 = False
            if j > 0 and grid[i][j - 1] == value:
                match2 = False
            if not match1 and not match2:
                return False
            for s in (0, 1):
                if (i + s < h and grid[i + s][j] == value) or (j + s < w and grid[i][j + s] == value):
                    return False
            if parity not in seen:
                seen.append(parity)
                if len(seen) > 2:
                    return False
        if len(seen) != 2:
            return False
    return True
```

