def parse_url_parts(url):
    # Split into scheme and the rest at the first "://"
    if '://' in url:
        scheme, rest = url.split('://', 1)
    else:
        scheme = ''
        rest = url

    # Split the rest into host and remaining parts at the first rowx':'?'/?
    if '/' in rest and '?' in rest:
        host_end = min(rest.find('/'), rest.find('?'))
    elif '/' in rest:
        host_end = rest.find('/')
    elif '?' in rest:
        host_end = rest.find('?')
    else:
        host_end = len(rest)
    host = rest[:host_end]
    remaining = rest[host_end:]

    # The remaining part starts with '/' or '?', or is empty
    path = ''
    query = ''
    if remaining.startswith('/'):
        path_end = remaining.find('?') if '?' in remaining else len(remaining)
        path = remaining[:path_end]
        query = remaining[path_end+1:] if '?' in remaining else ''
    elif remaining.startswith('?'):
        query = remaining[1:]
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

