def parse_list_range_spec(spec):
    tokens = spec.replace('-', ' ').split(',')
    result = []
    for token in tokens:
        if '-' in token:
            parts = token.split('-')
            A = int(parts[0])
            B = int(parts[1])
            result.extend(list(range(A, B + 1)))
        else:
            result.append(int(token))
    return sorted(result)
